mapper.select:
SELECT t.ctg_id as id, t.ctg_name as name, t.parent_ctg_id as parentId, t.sort_id as showOrder, t.is_active as isActive, t.rpt_dev_owner as rptDevOwner, t.biz_owner as bizOwner, t.oversized as oversized, t.is_module as isModule, t.ctg_desc as ctgDesc, t.etl_job as etlJob, t.data_dev_owner as dataDevOwner, t.is_auto_archive as isAutoArchive FROM ssd_field_ctg t WHERE t.`ctg_type` = 'front' and t.is_active = 1
and t.is_module = #{isModule}
ORDER BY parent_ctg_id, sort_id

