mapper.select:
SELECT count(1) as isShow, t3.dim_code as dimCode FROM ssd_field_def t1 INNER JOIN `ssm_field_ctg_rel` t2 ON t1.`field_id` = t2.`field_id` AND t2.`ctg_type` = 'front' INNER JOIN ssd_field_auth_dim t3 ON (t1.field_code = t3.field_code or t1.field_code = t3.white_paper_code) and t3.module_code = 'ssm_row' WHERE t1.is_active = 1 AND t2.is_active = 1 AND t2.ctg_id IN
#{item}
AND t3.dim_code IN
#{item}
GROUP BY t3.dim_code

