update ssd_field_ctg
    set is_active = 0 ,
        updated_time = now(),
        updated_by = #{userName}
where ctg_id = #{ctgId}

update ssd_field_ctg
    set sort_id = #{showOrder},
        updated_time = now(),
        updated_by = #{updatedBy}
where ctg_id = #{id}
